<template><div class="bm-panel flex flex-col gap-2 rounded-md p-3 sm:flex-row"><input :value="modelValue" class="bm-admin-input flex-1" placeholder="Buscar" @input="$emit('update:modelValue', ($event.target as HTMLInputElement).value)"><select v-if="statuses?.length" :value="status" class="bm-admin-input sm:max-w-56" @change="$emit('update:status', ($event.target as HTMLSelectElement).value)"><option value="">Todos os status</option><option v-for="item in statuses" :key="item">{{ item }}</option></select><UButton color="neutral" variant="soft" @click="$emit('reload')">Buscar</UButton></div></template>
<script setup lang="ts">defineProps<{ modelValue:string,status?:string,statuses?:string[] }>();defineEmits(['update:modelValue','update:status','reload'])</script>
